7	pub fn load(root: &Path) -> Result<SkillCatalog> {
8	    let root = root
9	        .canonicalize()
10	        .with_context(|| format!("Failed to resolve skills directory: {:?}", root))?;
11	    if !root.is_dir() {
12	        anyhow::bail!("Skills path is not a directory: {:?}", root);
13	    }
14	
15	    let mut paths = Vec::new();
16	    collect_markdown_files(&root, &mut paths)?;
17	    paths.sort();
18	
19	    let mut skills = Vec::new();
20	    for path in paths {
21	        let skill = parse_skill(&path)?;
22	        skills.push(skill);
23	    }
24	    SkillCatalog::new(skills)
25	}
