107	mod skill_called_as_tool_tests {
108	    use super::{skill_called_as_tool_message, LOAD_SKILL_ARGUMENT, LOAD_SKILL_TOOL};
109	
110	    /// The property is that the message names the call that works. A reviewer that saw
111	    /// only "expected server__tool" went on to tell a pull request it had run the skill.
112	    #[test]
113	    fn a_skill_path_is_told_which_tool_loads_it() {
114	        let message =
115	            skill_called_as_tool_message("engineering/environment").expect("a skill path");
116	        assert!(message.contains(LOAD_SKILL_TOOL));
117	        assert!(message.contains("engineering/environment"));
118	    }
119	
120	    /// The corrected call is one a model copies verbatim, so the argument's name has to
121	    /// be the one the tool takes.
122	    ///
123	    /// It was not. This message went on writing `{"name": ...}` after the schema became
124	    /// `skill_name` and every other spelling stopped being accepted, which made following
125	    /// it exactly a refusal. Nothing caught it: the key was a JSON string built here and
126	    /// a JSON string built in `application::tools`, and the assertions above name the
127	    /// tool and the skill but never the key.
128	    #[test]
129	    fn the_corrected_call_names_the_argument_the_tool_takes() {
130	        let message = skill_called_as_tool_message("engineering/tdd").expect("a skill path");
131	        assert!(
132	            message.contains(&format!(
133	                r#"{{"{LOAD_SKILL_ARGUMENT}": "engineering/tdd"}}"#
134	            )),
135	            "{message}"
136	        );
137	    }
138	
139	    /// It has to say that nothing happened, because the failure this came from was an
140	    /// agent reporting the skill as having run.
141	    #[test]
142	    fn the_message_says_nothing_has_run() {
143	        let message =
144	            skill_called_as_tool_message("review/quick-quality-gate").expect("a skill path");
145	        assert!(message.to_lowercase().contains("nothing has run"));
146	    }
147	
148	    /// A tool name that is simply wrong keeps the format error. Widening this to every
149	    /// unrecognised name would answer "did you mean a skill?" to a hallucinated tool,
150	    /// which reads as confirmation that the skill exists.
151	    #[test]
152	    fn a_name_that_is_not_a_skill_path_is_left_alone() {
153	        for name in ["github", "create_pr", "a/b/c", "/leading", "trailing/"] {
154	            assert!(
155	                skill_called_as_tool_message(name).is_none(),
156	                "{name} should keep the format error"
157	            );
158	        }
159	    }
160	}

