52	/// Split an MCP tool result's `content` into the text the model reads and the
53	/// image blocks it should see.
54	///
55	/// Images used to be folded into the text, where `serde_json::to_string` turned
56	/// each into a base64 blob the model could only read as characters — a picture
57	/// arriving as noise, and an expensive one. They now travel separately, in MCP's
58	/// own shape, for the LLM adapters to map.
59	///
60	/// Text keeps a `[image]` marker where each picture was, so its position in the
61	/// result stays legible: "the diagram below" means nothing once the diagram has
62	/// been lifted out.
63	///
64	/// Anything that is neither text nor image is still serialised into the text, as
65	/// before. An unknown block type is not a reason to lose it.
66	fn split_content(result: &Value) -> (String, Vec<Value>) {
67	    let Some(items) = result.get("content").and_then(|c| c.as_array()) else {
68	        return (
69	            serde_json::to_string(result).unwrap_or_default(),
70	            Vec::new(),
71	        );
72	    };
73	
74	    let mut images = Vec::new();
75	    let parts: Vec<String> = items
76	        .iter()
77	        .map(|item| {
78	            if let Some(text) = item.get("text").and_then(|t| t.as_str()) {
79	                return text.to_string();
80	            }
81	            if item.get("type").and_then(Value::as_str) == Some("image") {
82	                images.push(item.clone());
83	                return "[image]".to_string();
84	            }
85	            serde_json::to_string(item).unwrap_or_default()
86	        })
87	        .collect();
88	
89	    (parts.join("\n"), images)
90	}
