Good. Now the integration test. Create `tests/skill_catalog_test.rs`:

```rust
//! The skills this repository ships, loaded the way a run loads them.
//!
//! The catalog is what the prompt shows and what `load_skill` accepts, so a skill that
//! stops being found here is one no run can load -- and the layout that decides it
//! (`<category>/<skill-name>/SKILL.md`, https://agentskills.io/specification) is
//! asserted against the real tree rather than a fixture, because the fixture cannot be
//! wrong in the way a moved file is.

use std::path::Path;

#[test]
fn the_repositorys_skills_load_under_their_leaf_names() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join(".github/atomaton/skills");
    let catalog = atoma::infra::persistence::skill::load(&root).expect("the shipped skills load");

    let names: Vec<String> = catalog.metadata().into_iter().map(|m| m.name).collect();
    assert_eq!(
        names,
        vec![
            "agent-prompt-surface",
            "customer-doc",
            "environment",
            "gh-actions-surface",
            "japanese",
            "on-demand-audit",
            "pipeline-setup",
            "secrets-in-a-check",
            "web-search",
        ]
    );
}
```

